import{z as E,x as B,o as l,c as p,q as t,j as n,D as a,d as i,s as d,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"分词并行与预处理","description":"","frontmatter":{"title":"分词并行与预处理","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tokenizer-parallel.md","filePath":"llm/tokenizer-parallel.md","lastUpdated":1791413859000}'),c={name:"llm/tokenizer-parallel.md"};function P(A,e,m,f,h,T){const r=B("Mermaid");return l(),p("div",null,[e[2]||(e[2]=t('<h1 id="分词并行与预处理" tabindex="-1">分词并行与预处理 <a class="header-anchor" href="#分词并行与预处理" aria-label="Permalink to &quot;分词并行与预处理&quot;">​</a></h1><div class="epigraph"><p>GPU 等的常常不是注意力，而是主机上单线程的 BPE：提示一长，TTFT 的第一段已经花在 CPU 上。</p><footer>—— Sennrich et al., ACL 2016；Hugging Face tokenizers 用 Rust 并行处理批，见 Wolf et al., Transformers, EMNLP 2020 生态</footer></div><p><a href="/llm/moe-inference-batching">上一课</a>把 GPU 上的专家批凑厚。请求进引擎之前，字符串要变成 id。<a href="/llm/streaming-detokenize">流式 detokenize</a> 写的是输出侧；本课写输入侧：批内并行 encode、与 prefill 重叠、以及聊天模板。Wolf 等人的 Transformers 生态把高速分词做成独立库（Rust tokenizers）：多序列 <code>encode_batch</code>。服务若在 Python 里对每条请求 <code>tokenizer.encode</code>，长提示下 CPU 成为 TTFT 主项，会计里的 GPU 屋顶线根本摸不到。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>prefill 是算力绑定，但启动前必须有 id 张量。单条 100K 字符的文档，BPE 是线性扫描加堆合并，可以到数十毫秒以上，且难在 GPU 上做（规则与模型绑定、分支多）。缺口是：把分词当成服务流水的独立阶段——线程池、批、缓存——而不是模型 <code>__call__</code> 的前奏。聊天模板（加 special tokens、角色标记）必须与训练一致；模板在 Python 字符串上做完再 encode，不要 encode 后再手工插 id 除非测试对齐。</p><p><span class="marginnote">TTFT（Time To First Token）就是用户从发出请求到看到第一个字所等的时间。分词在 CPU 上串行跑，正占着这段等待的前半截——GPU 再快，也救不回主机上没并行的 BPE。</span></p><p>缓存：系统提示、工具 schema 的 token 应缓存 id，不要每请求重分词。这与 KV 前缀缓存是两层：id 缓存省 CPU，KV 缓存省 GPU。</p><p><span class="marginnote">直觉类比：id 缓存像把常点菜的「菜谱」抄好备用，省下每次查菜谱的 CPU 时间；KV 缓存像把菜提前做成半成品，省下 GPU 的重算。两层各省一段，别当成一个开关。</span></p><p><span class="marginnote">detokenize 的稳定前缀协议不要与 encode 共享一个锁。一边流式出、一边进新请求，分词器实现必须线程安全或按请求克隆。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对到达队列做 <code>encode_batch</code>（Rust 侧 rayon 并行），不要 GIL 里逐条。超长单条内部也可切段并行再拼接——仅当分词器允许无跨段状态；BPE 通常要整段。与 GPU：CPU 分词与上一批 prefill 重叠。多模态下一课才加视觉编码器；文本 id 应先就绪，免得视觉流水还等分词。</p><p>词表与 <a href="/llm/logit-bias">logit bias</a> 的 id 列表应在部署时预编译。停用词同理。</p>',12)),(l(),n(s,null,{default:a(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E5%AD%97%E7%AC%A6%E4%B8%B2%20%2B%20%E6%A8%A1%E6%9D%BF%22%5D%20--%3E%20BAT%5B%22encode_batch%20%E7%BA%BF%E7%A8%8B%E6%B1%A0%22%5D%0A%20%20BAT%20--%3E%20ID%5B%22id%20%E5%BC%A0%E9%87%8F%22%5D%0A%20%20ID%20--%3E%20GPU%5B%22prefill%22%5D%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%20id%20%E7%BC%93%E5%AD%98%22%5D%20--%3E%20ID%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[i("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,"TTFT = 排队 + 分词 + 搬输入 + prefill。长上下文曲线若只画 GPU，会漏掉第一项。byte-level BPE 对任意字节合法，预分词正则（如 GPT-2 的）可能成为扫描瓶颈，那是预训练工程课的正则；服务侧能做的是并行与缓存。错误的并行（按字符切 BPE）会改变合并，id 与训练不一致，属于静默正确性 bug。",-1)),(l(),n(s,null,{default:a(()=>[d(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E8%AF%B7%E6%B1%82%E5%85%A5%E9%98%9F%22%5D%20--%3E%20E%5B%22CPU%20%E5%88%86%E8%AF%8D%22%5D%0A%20%20E%20--%3E%20H%5B%22%E6%90%AC%E8%BF%90%20id%20%E5%BC%A0%E9%87%8F%22%5D%0A%20%20H%20--%3E%20P%5B%22GPU%20prefill%22%5D%0A%20%20C%5B%22%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%20id%20%E7%BC%93%E5%AD%98%22%5D%20-.%20%22%E5%91%BD%E4%B8%AD%E5%88%99%E8%B7%B3%E8%BF%87%22%20.-%3E%20E%0A%20%20P%20-.%20%22%E7%A9%BA%E9%97%B2%E6%97%B6%E6%AE%B5%E9%87%8D%E5%8F%A0%E4%B8%8B%E4%B8%80%E8%AF%B7%E6%B1%82%22%20.-%3E%20E%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=t('<p><span class="marginnote">常见误区：为了并行把一段话按字符硬切成几块分别做 BPE。合并要看前后文，切开算出的 id 可能和整段不一致，模型读到的相当于「错别字」，而且不报错——这正是正文说的静默正确性 bug。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在 GPU 核里重写一份不完全一致的 BPE。不要为了并行破坏确定性。下一课：视觉编码器如何与文本 prefill 排成流水，而不是先把图编码完再开始一切。</p><p>出处：Sennrich et al., ACL 2016；Wolf et al., EMNLP 2020（Transformers）。Hugging Face tokenizers 库为实现出处。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分词是 TTFT 的 CPU 段；长提示上可以盖过短 prefill。</li><li><code>encode_batch</code> + 系统提示 id 缓存；与 GPU 重叠。</li><li>模板与训练对齐；禁止不安全的切段 BPE。</li><li>id 缓存与 KV 缓存是两层。</li><li>线程安全：进出流式同时发生。</li><li>下一课：多模态编码器流水。</li><li>出处：Sennrich et al., 2016；Wolf et al., 2020。</li></ul>',6))])}const D=E(c,[["render",P]]);export{u as __pageData,D as default};
